<?php require 'includes/functions.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('/movie-booking/index.php');check_csrf();$show=(int)$_POST['show_id'];$seats=array_values(array_unique(array_filter(explode(',',$_POST['seats']??''),function($x){return preg_match('/^[A-J](?:[1-9]|1[0-2])$/',$x);})));if(!$seats||count($seats)>10){flash('error','Choose between 1 and 10 valid seats.');redirect('/movie-booking/booking.php?show='.$show);}try{$pdo=db();$pdo->beginTransaction();$q=$pdo->prepare('SELECT s.*,m.title,m.poster,t.name theater,sc.name screen FROM shows s JOIN movies m ON m.id=s.movie_id JOIN screens sc ON sc.id=s.screen_id JOIN theaters t ON t.id=sc.theater_id WHERE s.id=? FOR UPDATE');$q->execute([$show]);$sh=$q->fetch();if(!$sh)throw new Exception('Show unavailable.');$check=$pdo->prepare("SELECT bs.seat_number FROM booked_seats bs JOIN bookings b ON b.id=bs.booking_id WHERE bs.show_id=? AND bs.seat_number IN (".implode(',',array_fill(0,count($seats),'?')).") AND b.status='confirmed'");$check->execute(array_merge([$show],$seats));if($taken=$check->fetchColumn())throw new Exception("Seat $taken was just booked. Please choose another.");$code='CV'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$total=$sh['ticket_price']*count($seats);$pdo->prepare('INSERT INTO bookings(booking_code,user_id,show_id,total_amount) VALUES(?,?,?,?)')->execute([$code,$_SESSION['user']['id'],$show,$total]);$bid=$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO booked_seats(booking_id,show_id,seat_number) VALUES(?,?,?)');foreach($seats as $seat)$ins->execute([$bid,$show,$seat]);$pdo->prepare('INSERT INTO payments(booking_id,amount) VALUES(?,?)')->execute([$bid,$total]);$pdo->commit();redirect('/movie-booking/ticket.php?id='.$bid);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e->getMessage());redirect('/movie-booking/booking.php?show='.$show);}
